async itemExists(id) {
  return id in (await this.getAllIDs());
},

/**
 * Obtain the set of all known record IDs.
 *
 * @returns {object}
 */
async getAllIDs() {
  const ids = {};
  const keys = await getDataKeys(this.name);
  for (const k of keys) {
    if (!this._deleted.has(ids[k])) {
      ids[k] = true;
    }
  }
  return ids;
